const unifiedItems = [];

try {
  const hnData = $('Fetch Hacker News').first()?.json;
  const hnHits = hnData?.hits || [];

  for (const hit of hnHits.slice(0, 5)) {
    const itemUrl = hit.url || `https://news.ycombinator.com/item?id=${hit.objectID}`;
    unifiedItems.push({
      json: {
        source: 'hackernews',
        title: hit.title || 'Untitled HN Discussion',
        item_url: itemUrl,
        author: hit.author || 'Anonymous',
        content_snippet: hit.story_text || `HN Points: ${hit.points || 0} | Comments: ${hit.num_comments || 0}`
      }
    });
  }
} catch (err) {
  console.log('Error parsing Hacker News:', err.message);
}


try {
  const rssItems = $('Fetch Hugging Face RSS').all();

  for (const item of rssItems.slice(0, 5)) {
    const data = item.json;
    unifiedItems.push({
      json: {
        source: 'rss',
        title: data.title || 'Untitled Blog Post',
        item_url: data.link || '',
        author: data.creator || 'Hugging Face Research',
        content_snippet: (data.contentSnippet || data.content || '').substring(0, 400)
      }
    });
  }
} catch (err) {
  console.log('Error parsing RSS:', err.message);
}

try {
  const arxivRaw = $('Fetch arXiv Papers').first()?.json?.data || '';
  const entryMatches = arxivRaw.match(/<entry>[\s\S]*?<\/entry>/g) || [];

  for (const entry of entryMatches.slice(0, 5)) {
    const titleMatch = entry.match(/<title>([\s\S]*?)<\/title>/);
    const idMatch = entry.match(/<id>([\s\S]*?)<\/id>/);
    const summaryMatch = entry.match(/<summary>([\s\S]*?)<\/summary>/);
    const authorMatch = entry.match(/<author>\s*<name>(.*?)<\/name>/);

    const title = titleMatch ? titleMatch[1].replace(/\n/g, ' ').trim() : 'Untitled Paper';
    const itemUrl = idMatch ? idMatch[1].trim() : '';
    const summary = summaryMatch ? summaryMatch[1].replace(/\n/g, ' ').trim().substring(0, 400) : '';
    const author = authorMatch ? authorMatch[1].trim() : 'arXiv Author';

    if (itemUrl) {
      unifiedItems.push({
        json: {
          source: 'arxiv',
          title: title,
          item_url: itemUrl,
          author: author,
          content_snippet: summary
        }
      });
    }
  }
} catch (err) {
  console.log('Error parsing arXiv:', err.message);
}

return unifiedItems;

