let staticData = {};
try {
  staticData = $getWorkflowStaticData('global');
} catch (e) {
  staticData = {};
}
staticData.seenUrls = staticData.seenUrls || [];

const items = $input.all();
const brandNewItems = [];

for (const item of items) {
  const url = item.json.item_url;
  if (url && !staticData.seenUrls.includes(url)) {
    brandNewItems.push(item);
    staticData.seenUrls.push(url);
  }
}

if (staticData.seenUrls.length > 500) {
  staticData.seenUrls = staticData.seenUrls.slice(-500);
}

if (brandNewItems.length === 0) {
  return [{
    json: {
      is_up_to_date: true,
      source: 'arxiv',
      title: 'Active Scope Up to Date',
      item_url: '',
      relevance_score: 10,
      ai_summary: 'All recent arXiv papers, Hacker News discussions, and technical publications have already been indexed. No new breakthroughs published in the interim.',
      why_it_matters: 'Confirms continuous monitoring while preventing duplicate alerts.'
    }
  }];
}

return brandNewItems;

const items = $input.all();
const formatted = [];
const today = new Date().toISOString().split('T')[0];

for (let i = 0; i < items.length; i++) {
  const groqRes = items[i].json;
  const original = $('Filter High Relevance').all()[i]?.json || {};
  let summary = 'Executive briefing pending.';
  let why = '';
  try {
    const raw = groqRes.choices?.[0]?.message?.content || '{}';
    const parsed = JSON.parse(raw);
    summary = parsed.ai_summary || summary;
    why = parsed.why_it_matters || '';
  } catch (e) {
    summary = groqRes.choices?.[0]?.message?.content || summary;
  }

  formatted.push({
    json: {
      id: `digest_${Date.now()}_${i}`,
      source: original.source || 'arxiv',
      title: original.title || 'Untitled Research Breakthrough',
      item_url: original.item_url || '',
      author_or_submitter: original.author || 'AI Research Lab',
      relevance_score: original.relevance_score || 8,
      ai_summary: summary,
      why_it_matters: why,
      digest_date: today,
      delivered_to_feed: true,
      created_at: new Date().toISOString()
    }
  });
}

if (formatted.length === 0) {
  formatted.push({
    json: {
      id: `digest_cached_${Date.now()}`,
      source: 'arxiv',
      title: 'Autonomous Scope Up to Date',
      item_url: '',
      author_or_submitter: 'EchoAgent Pipeline',
      relevance_score: 9,
      ai_summary: 'All recent arXiv preprints, Hacker News discussions, and Hugging Face releases are currently monitored and indexed.',
      why_it_matters: 'Validates automated 24/7 background intelligence loop with zero redundant overhead.',
      digest_date: today,
      delivered_to_feed: true,
      created_at: new Date().toISOString()
    }
  });
}

return formatted;

